#!/usr/bin/env python3
# apply_tvx_mobile.py — TVX_MOBILE_20261011   (requires TVX_MULTI_20261009)
# ============================================================================
# TV Alerts on the phone (Tailscale): the page gets a phone layout (< 768px —
# the app's useIsMobile): tighter padding, alerts and closed trades as cards
# (tap a trade for its option / futures-or-spot range), range labels trimmed;
# and an admin-only "TV Alerts" tab in the mobile bottom bar.
#
# Self-contained. RUN ONLY THIS SCRIPT.
#   cd ~/dev/scalp-app && python3 apply_tvx_mobile.py [--dry-run] [--allow-dirty]
#
# REPLACES frontend/src/pages/TvAlerts.jsx (must still be the exact TVX_MULTI
#          version — sha256-guarded)
# EDITS    frontend/src/App.jsx (2 anchored inserts in BottomTabBar)
# Mirrors into desktop/src-tauri/frontend when present. Frontend only.
# ============================================================================
import argparse, base64, hashlib, os, shutil, subprocess, sys, tempfile
from pathlib import Path

FENCE = "TVX_MOBILE_20261011"
TV = "frontend/src/pages/TvAlerts.jsx"
APP = "frontend/src/App.jsx"
TV_OLD_SHA = "26393c49b2a502e9a4f62381132a8ac1fbef4331c86e42cd2963338a8765f36c"
TV_NEW = ("", "0459197fff75fb287e7ff275dc8eabadef68ef7a157e115fa13b6645b9c7a6b6")
APP_EDITS = [('function BottomTabBar({ health }) {\n  const location = useLocation();\n', 'function BottomTabBar({ health }) {\n  const location = useLocation();\n  const { isAdminUi } = useEntitlements();                         // ── TVX_MOBILE_20261011 ──\n'), ('    { path: "/connections",  label: "Connect",   icon: "🔗" },\n  ];\n', '    { path: "/connections",  label: "Connect",   icon: "🔗" },\n  ];\n  if (isAdminUi) tabs.splice(3, 0, { path: "/tv-alerts", label: "TV Alerts", icon: "📡" });   // ── TVX_MOBILE_20261011 ── admin only\n')]
MIRROR = "desktop/src-tauri/frontend/"

def die(m):
    print(f"\n✖ ABORT: {m}\nNothing was written."); sys.exit(1)
def ok(m): print(f"  ✓ {m}")

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--dry-run", action="store_true"); ap.add_argument("--allow-dirty", action="store_true")
    a = ap.parse_args(); root = Path.cwd()
    print(f"apply_tvx_mobile.py — {FENCE}  (repo: {root})\n")
    for p in (TV, APP):
        if not (root / p).is_file(): die(f"{p} not found — run from the scalp-app repo root")
    tv, app = (root / TV).read_text(), (root / APP).read_text()
    if FENCE in tv or FENCE in app: die(f"{FENCE} already present — already applied")
    if "TVX_MULTI_20261009" not in tv: die("TVX_MULTI_20261009 is not applied — run apply_tvx_multi.py first")
    if hashlib.sha256((root / TV).read_bytes()).hexdigest() != TV_OLD_SHA:
        die(f"{TV} differs from the TVX_MULTI version (edited by hand?). Restore it and re-run")
    ok("parent TVX_MULTI present, TvAlerts.jsx unchanged (sha256)")
    try:
        st = subprocess.run(["git", "status", "--porcelain", "--", TV, APP], cwd=root, capture_output=True, text=True, timeout=30).stdout
    except Exception: st = ""
    mods = [l for l in st.splitlines() if l[:2].strip().startswith("M")]
    if mods and not a.allow_dirty: die("uncommitted modifications:\n" + "\n".join(mods) + "\nCommit first, or --allow-dirty")
    ok("git: no uncommitted edits on targets" if not mods else "dirty targets allowed")
    new_tv = base64.b64decode(TV_NEW[0])
    if hashlib.sha256(new_tv).hexdigest() != TV_NEW[1]: die("payload checksum mismatch")
    new_tv = new_tv.decode()
    for old, new in APP_EDITS:
        n = app.count(old)
        if n != 1: die(f"App.jsx anchor found {n}× (need 1):\n    {old.strip()[:100]}")
        app = app.replace(old, new)
    ok("payload verified; 2 App.jsx anchors matched once")
    esb = next((c for c in (root / "frontend/node_modules/.bin/esbuild", root / "desktop/node_modules/.bin/esbuild",
                            root / "desktop/src-tauri/frontend/node_modules/.bin/esbuild") if c.exists()), None) or shutil.which("esbuild")
    if esb:
        with tempfile.TemporaryDirectory() as td:
            for name, text in (("TvAlerts.jsx", new_tv), ("App.jsx", app)):
                f = Path(td) / name; f.write_text(text)
                r = subprocess.run([str(esb), str(f), "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error"], capture_output=True, text=True, timeout=60)
                if r.returncode != 0: die(f"esbuild could not parse {name}:\n{r.stderr[-1500:]}")
        ok(f"esbuild parsed TvAlerts.jsx + App.jsx ({esb})")
    else:
        print("  ! esbuild not found — JSX parse skipped (build-scalp.sh will compile it)")
    plan = [(root / TV, new_tv), (root / APP, app)]
    if (root / MIRROR).is_dir():
        plan += [(root / (MIRROR + TV[len("frontend/"):]), new_tv), (root / (MIRROR + APP[len("frontend/"):]), app)]
    if a.dry_run:
        print("\nDRY RUN — would write:"); [print(f"    {f.relative_to(root)}") for f, _ in plan]; return
    done = []
    try:
        for f, text in plan:
            bak = None
            if f.exists():
                bak = f.with_name(f.name + f".bak-{FENCE}"); shutil.copy2(f, bak)
            f.parent.mkdir(parents=True, exist_ok=True)
            tmp = f.with_name(f.name + ".mob-tmp"); tmp.write_text(text); os.replace(tmp, f)
            done.append((f, bak))
    except Exception as e:
        for f, bak in reversed(done):
            if bak: shutil.copy2(bak, f); bak.unlink(missing_ok=True)
        die(f"write failed ({e}) — rolled back")
    print("\nWritten:"); [print(f"    {f.relative_to(root)}") for f, _ in done]
    print(f"""
✔ {FENCE} applied.

Next:
  1. git add {TV} {APP}
     git commit -m "{FENCE}: TV Alerts phone layout + mobile tab"
  2. ./desktop/build-scalp.sh both      (frontend-only change)
""")

if __name__ == "__main__":
    main()
